from pysat.formula import CNF
from pysat.solvers import Solver

# Encode the pigeonhole problem:
# 5 pigeons, 4 holes
# Each pigeon must be in exactly one hole
# Each hole can contain at most one pigeon

num_pigeons = 5
num_holes = 4

# Variable x[i][j] = True means pigeon i is in hole j
# We'll encode variable (i, j) as i * num_holes + j + 1 (1-indexed for SAT)

def var(i, j):
    return i * num_holes + j + 1

cnf = CNF()

# Constraint 1: Each pigeon must be in AT LEAST one hole
for i in range(num_pigeons):
    cnf.append([var(i, j) for j in range(num_holes)])

# Constraint 2: Each pigeon is in AT MOST one hole (optional for PHP but let's be complete)
for i in range(num_pigeons):
    for j1 in range(num_holes):
        for j2 in range(j1 + 1, num_holes):
            cnf.append([-var(i, j1), -var(i, j2)])

# Constraint 3: Each hole contains AT MOST one pigeon
for j in range(num_holes):
    for i1 in range(num_pigeons):
        for i2 in range(i1 + 1, num_pigeons):
            cnf.append([-var(i1, j), -var(i2, j)])

with Solver(name='glucose3', bootstrap_with=cnf) as solver:
    result = solver.solve()
    print(f"Satisfiable: {result}")
    if result:
        model = solver.get_model()
        assignment = []
        for i in range(num_pigeons):
            for j in range(num_holes):
                if var(i, j) in model:
                    assignment.append(j)
                    break
        print(f"Assignment: {assignment}")
    else:
        print("UNSATISFIABLE — no solution exists")
